cd /office; python3 - <<'PYEOF'
import re, glob, csv
from collections import defaultdict
onsite = {"东港":"潮册","西湾":"栈册","南站":"桐册","北仓":"丁册"}
raw={}
for path in sorted(glob.glob("inbox/06-02/*联席纪要.txt")):
    txt=open(path,encoding="utf-8").read()
    station=re.search(r"(\S+?)联席纪要", txt).group(1)
    for b in re.split(r"\n(?=议案 )", txt):
        m=re.match(r"议案\s+(\d+)\s+客户\s+(J\d+)", b)
        if not m: continue
        yian,case=m.group(1),m.group(2); clauses={}
        for line in b.splitlines():
            cm=re.match(r"(\S+册)｜(.*)", line.strip())
            if not cm: continue
            book,body=cm.group(1),cm.group(2)
            status="草案" if "草案" in body else "正本"
            per=re.search(r"六月(\d+)日至(\d+)日", body); start=int(per.group(1))
            m1=re.search(r"核给(\d+)席.*?优先号(\d+)",body); m2=re.search(r"办理顺位(\d+).*?额度(\d+)席",body); m3=re.search(r"留位为(\d+)席.*?优先号(\d+)",body)
            if m1: q,p=int(m1.group(1)),int(m1.group(2))
            elif m2: p,q=int(m2.group(1)),int(m2.group(2))
            else: q,p=int(m3.group(1)),int(m3.group(2))
            clauses[book]=(q,p,start,status)
        raw[(station,yian)]=(case,clauses)

cand=defaultdict(list)
for (station,yian),(case,clauses) in raw.items():
    q,p,start,status=clauses[onsite[station]]
    cand[case].append(dict(yian=int(yian),quota=q,prio=p,start=start,status=status,station=station))

out=[]
for case in sorted(cand):
    valid=[c for c in cand[case] if c["status"]=="正本" and c["start"]<=3]
    assert valid, case
    pick=max(valid,key=lambda c:(c["start"],c["yian"]))  # 生效日, 流水数值 最大
    out.append((case,pick["yian"],pick["quota"],pick["prio"],pick["station"]))

with open("out/授权.csv","w",newline="",encoding="utf-8-sig") as f:
    w=csv.writer(f); w.writerow(["案号","批文","额度","优先号"])
    for case,y,q,p,st in out: w.writerow([case,y,q,p])

print("案号 批文 额度 优先号  (站)")
for case,y,q,p,st in out: print(case,y,q,p,st)
print("\n回退章程的案:", [c for c,_,_,_,_ in out if False])
PYEOF
echo "=== out/授权.csv ==="; cat out/授权.csv
